using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class MarinaCompactPropLayout{static MarinaCompactPropLayout(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("MarinaCompactPropLayout.request"))return;File.Delete("MarinaCompactPropLayout.request");const string D="Assets/Scenes/Oasis/YachtPortAtlas";var r=PrefabUtility.LoadPrefabContents(D+"/Marina Existing City Props Features.prefab");var main=AssetDatabase.LoadAssetAtPath<Mesh>(D+"/Meshes/Grand Ground Level Yacht Yard.asset");float y=main.vertices.Max(v=>v.y),cx=main.bounds.center.x,w=main.bounds.size.x,d=main.bounds.size.z;foreach(string name in new[]{"Garden Lamp","Striped Road Bollard","Traffic Cone","Yellow Barrier"}){var props=r.transform.Cast<Transform>().Where(t=>t.name.Contains("Existing "+name)).ToArray();for(int i=0;i<props.Length;i++){float x=0,z=0;if(name=="Garden Lamp"){bool front=i<6;x=cx-w/2+6+(front?i*(w-12)/5:(i-6)*(w-12)/3);z=front?-d/2+2:d/2-2;}if(name=="Striped Road Bollard"){int n=props.Length/2;bool front=i<n;x=cx-w/2+4+(i%n)*(w-8)/(n-1);z=front?-d/2+1:d/2-1;}if(name=="Traffic Cone"){x=cx-w*.34f-14+(i%4)*9.3f;z=i<4?-17:17;}if(name=="Yellow Barrier"){x=cx+12+i*12;z=d/2-2;}props[i].localPosition=new Vector3(x,y,z);}}PrefabUtility.SaveAsPrefabAsset(r,D+"/Marina Existing City Props Features.prefab");PrefabUtility.UnloadPrefabContents(r);AssetDatabase.SaveAssets();File.WriteAllText("FinalEnvironmentRoadReview/MarinaCompactPropLayout.txt","SUCCESS all existing city props aligned to compact yard bounds.");}}
